create table stock_out_order
(
    order_id            bigint auto_increment comment '主键'
        primary key,
    order_no            varchar(64)                     null comment '单据号',
    order_type          varchar(32)                     null comment '单据类型',
    prod_order_no       varchar(64)                     null comment '生产订单号',
    customer_order_no   varchar(30)                     null comment '关联客户订单号',
    warehouse_code      varchar(64)                     null comment '仓库',
    workshop_code       varchar(64)                     null comment '车间',
    order_reason        varchar(255)                    null comment '原因',
    mat_code            varchar(64)                     null comment '物料编码',
    mat_name            varchar(128)                    null comment '物料名称',
    quantity            decimal(24, 6) default 0.000000 null comment '数量',
    order_status        varchar(32)                     null comment '单据状态',
    warehouse_keeper    varchar(64)                     null comment '库管员',
    del_flag            char           default '0'      null comment '删除标识',
    create_by           varchar(64)                     null comment '创建人',
    create_time         datetime                        null comment '创建时间',
    update_by           varchar(64)                     null comment '修改人',
    update_time         datetime                        null comment '修改时间',
    allot_no            varchar(32)                     null comment '关联调拨单号',
    dest_warehouse_code varchar(32)                     null comment '目标仓库编码'
)
    comment '出库单' collate = utf8mb4_general_ci
                     row_format = DYNAMIC;

create index idx_out_order_allot_no
    on stock_out_order (allot_no);

